"""Report the qualified interface separately from unavailable hydraulic observations."""
from pathlib import Path
import sys,json,re,html,shutil
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'src/preprocessing'))
from prepare_sfincs_negative_trace import OUT,REPORT
from prepare_sfincs_cpu_build import sha,dump

def main():
 out=ROOT/OUT;report=ROOT/REPORT
 if(out/'freeze.json').exists():raise FileExistsError('Frozen interface')
 v=json.loads((report/'validation.json').read_text());assert v['all_checks_passed']
 meta=json.loads((out/'metadata_binding.json').read_text());top=json.loads((out/'whole_domain_metadata/topology_fixture.json').read_text());schema=json.loads((out/'output_schema.json').read_text())
 schema['native_flux_layout']='Pinned SFINCS one-based q(1:npuv+1), with tail dummy for absent faces; exported absent face index normalized to0 with face_exists=false.'
 schema['geometry_admission']='Existing fixed regular10m geometry only; mapped and native face minima must agree. New geometry or other solver profiles require qualification.'
 dump(out/'output_schema.json',schema)
 # Reusable schema and representative test aggregates are explicitly named as fixtures.
 for name in ['output_schema.json','metadata_binding.json','solver_binding.json']:
  shutil.copyfile(out/name,report/name)
 shutil.copytree(out/'interface_tests/normal_grouped',report/'prescribed_fixture_group_example',dirs_exist_ok=True)
 text=f'''# 负体积跨阈值与触发格面：接口已实现并核验\n\n本轮完成诊断接口、完整CPU镜像链接与水域组汇总。{len(v['checks'])}项检查全部通过。没有初始化或推进水动力求解器，没有新洪水结果，没有训练或执行58个情景。Framelog MILI-D-20261015-011。\n\n## 实际可新增的记录\n\n- 每个内部原生单元：首次／末次低于 -0.001 m³ 的实际步末端时刻、全过程最小有符号体积、最小值最早出现时刻和步号、负值步数、向下／向上穿越次数，以及初始就低于阈值的标记。未发生项的时刻留空。\n- 每次跨阈值：事件编号、单元编号、前后实际时刻、dt、前后体积、原生连续方程实际水平增量、理论施加雨量项和浮点加法后的实际雨量增量。\n- 同一步四向格面：原生面与邻格编号、方向、原生q、横向宽度、带符号交换量、开放宽度／道路宽度、映射面最低高程／运行时面最低高程和水域组。缺失格面明确标记，不把缺失地形当零高程。\n- 分别保留单面项合计与原连续方程分组计算的舍入差，以及双精度体积更新余差；不通过裁零制造闭合，不改变原水动力方程。\n\n“跨阈值时刻”指实际计算步末端首次观测低于阈值；连续时间的真实穿越只被前后步端点夹住。负值步数不等于精确连续持续时间。初始已负仅记录初态，不伪造导致初态的格面事件。\n\n## 水域组如何汇总\n\n保留17隅田川、51未命名水体、71亀島川、79古川、106日本橋川、110神田川、111古川七个代码，不合并同名古川。单元按真实开放的规定水位格面连接归属；没有直接连接者单列0，不按最近河流分配。多组连接保留多重归属，分组数量不能直接相加当全域唯一单元数。\n\n另按触发格面的边界组累计流入、流出和有符号交换；非边界面／缺失面单列0。这是“跨阈值步骤的格面观测”，不是全事件水量预算，重复步骤和共同格面不能伪装成新增交换量。聚合器会拒绝漏面、重复方向、未知组代码或不一致时钟。\n\n## 核验覆盖\n\n- 完整生产库：GNU Fortran与实际Fortran NetCDF链接、动态加载、原公开预算入口和新诊断输出。\n- 原生布局：通量从1开始，缺失格面使用末尾哑元。非零哑元、错误指针和不支持的加密模式均被拒收。\n- 全域元数据：{meta['native_cells']:,}个活动单元，其中{meta['interior_cells']:,}个内部单元、{meta['boundary_cells']:,}个规定水位单元；{top['native_faces']:,}个原生面。按固定源码的东向／北向面顺序，用实际子网格面高程检查所有现存内部格面，水域组连接与现有图逐项一致。该测试只给定零记账状态并调用诊断初始化／关闭，水动力初始化和时间推进均为零。\n- 预设数组算例：非均匀dt、重复跨阈值和恢复、初态负值、恰等于阈值不判负、最小值时刻、源项与格面符号、宽度不重复相乘、串行／4线程逐字节一致。启用／关闭诊断后的预算与状态一致。\n- 回归：14个旧预算接口算例与57个降雨读取算例通过，包括原50份情景输入的时间节点和日期参考兼容。\n\n初版小算例使用了不同的哑元表示；源码对照后修正，并重新构建／核验。初版源码绑定、镜像ID和测试证据保存在 attempts，不能作为最终部署资格。内部Fortran辅助例程保持私有；核验通过公开预算入口及真实生产输出，不新增外部ABI要求。\n\n## 交付与使用范围\n\n当前镜像 `{v['new_image_id']}`，完整补丁 `{v['new_patch_sha256']}`。镜像离线归档、源绑定、原生元数据及输出合同在 {OUT}。\n\n未来被单独授权的新运行必须：使用绑定镜像与补丁，校验原生网格及侧车映射哈希，提供诊断请求和映射，确认运行回执显示已启用。没有请求时保留旧接口行为；部署校验不得把这种兼容关闭状态当成已采集触发诊断。触发面采样只在穿越时输出，另有线性规模的单元汇总，不导出全部格面的全时空立方体。额外运行时间尚未在全域时间积分中测量。\n\n现有两组的真实首次／最小值逐格记录和触发格面历史仍不能从旧输出恢复。报告中的预设算例及分组示例不是东京实际水动力结果。要得到真实成因证据，下一步需另行授权用新接口有限重放同一干组和降雨组；当前未执行。原曲线、谱系、划分、旧标签、准入阈值及默认参考加载器保留，训练仍关闭。\n\nAnaSOP仅第4、6、7节记录诊断构建、解释边界与后续工作；不新增最终预测变量、阈值或公式。\n'''
 (report/'README.md').write_text(text)
 esc=html.escape
 testrows=''.join('<tr><td>'+esc(c['check'])+'</td><td>'+('PASS'if c['pass']else'FAIL')+'</td></tr>'for c in v['checks'])
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>负体积触发诊断接口核验</title><style>body{font:16px/1.8 system-ui,sans-serif;background:#eff3f5;color:#203a47;margin:0}main{max-width:1080px;margin:auto;padding:28px}section{background:white;border:1px solid #dce5e8;border-radius:12px;padding:24px;margin:18px 0}h1{font-size:29px;line-height:1.45}h2{font-size:21px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:#eaf3f3;border-radius:10px;padding:17px}.card strong{display:block;font-size:27px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:8px;text-align:left;border-bottom:1px solid #dce5e8}.scroll{overflow:auto}a{color:#146d82}.note{border-left:4px solid #c38b43;padding-left:16px}code{overflow-wrap:anywhere;font-size:12px}@media(max-width:650px){main{padding:12px}section{padding:17px}.cards{grid-template-columns:1fr}}</style><main><p>Mili · 全域10 m · 诊断接口</p><h1>跨阈值时刻、最小体积与触发格面<br>已实现并完成生产库接口核验</h1><p class="note">本轮没有新水动力模拟。旧两组真实触发历史没有回填；下方数据示例来自预设记账算例。</p><section><div class="cards"><div class="card"><strong>__CHECKS__ 项</strong>接口与回归检查全部通过</div><div class="card"><strong>358,384 格</strong>全域内部原生元数据核验</div><div class="card"><strong>0 次</strong>水动力初始化／更新</div></div></section><section><h2>可直接采集的诊断</h2><p>逐格保存首次／末次低于阈值的实际步端点、最小体积与时刻、负值步数、重复跨越及恢复。每次跨阈值保存同一步前后体积、实际降雨增量和四向格面交换，附带原生面、邻格、开放宽度及面高程。</p><p>保留格面合计与原连续方程分组计算的舍入差。有符号储量不裁零，原计算方程不改。跨阈值的连续时间只被前后步端点夹住，负值步数不作为精确持续时间。</p></section><section><h2>按真实开放连接归属水域</h2><p>使用7个既有水域代码，保留两个同名古川的区别；多组连接保留多重归属，没有直接接收面者单列。不会把每个单元强行分配给最近河流。</p><p>分组的触发格面交换与全事件预算分开，避免重复面／重复跨阈值造成误解。聚合器对漏面、重复方向、未知组代码或时钟不一致拒收。</p></section><section><h2>核验到哪一层</h2><p>CPU完整库重新编译链接；预设算例验证非均匀dt、向下／向上跨阈值、初始负值、阈值等号、逐面符号和舍入。串行／4线程输出一致，启用／关闭诊断的原预算一致。14个旧预算和57个降雨读取回归通过。</p><p>全域实际索引、面序与子网格高程用于纯元数据算例，全部内部格面的映射通过检查，开放水域连接与既有图一致。没有调用水动力初始化、动量、连续方程或求解器更新时间步。</p></section><section><h2>当前结论与下一步</h2><p class="note">已经具备采集真实触发证据的接口；尚未得到现有两组新的触发数据，不能据此认定负体积成因已解决或参考标签可放行。</p><p>下一步如获单独授权，可只重放原干组和降雨组，保持科学曲线和几何，取得按水域组汇总的真实触发记录。当前未训练、未运行58个情景，原标签和准入政策保留。</p><p>镜像版本：<code>__IMAGE__</code></p></section><section><h2>交付证据</h2><p><a href="README.md">完整说明</a> · <a href="output_schema.json">输出合同</a> · <a href="metadata_binding.json">全域元数据绑定</a> · <a href="solver_binding.json">镜像绑定</a> · <a href="validation.json">全部检查</a> · <a href="prescribed_fixture_group_example/water_group_cell_summary.csv">预设算例的水域组示例</a> · <a href="prescribed_fixture_group_example/water_group_crossing_face_summary.csv">预设算例的触发面汇总</a></p><details><summary>展开__CHECKS__项检查</summary><div class="scroll"><table><tr><th>检查</th><th>状态</th></tr>__TESTS__</table></div></details></section></main></html>'''
 (report/'review.html').write_text(page.replace('__CHECKS__',str(len(v['checks']))).replace('__IMAGE__',esc(v['new_image_id'])).replace('__TESTS__',testrows))
 # Skill-routed addenda only; reuse the established questions, candidate roles and figure plan.
 p=ROOT/'docs/AnaSOP.md';backup=report/'previous-AnaSOP.md'
 if not backup.exists():backup.write_bytes(p.read_bytes())
 before=p.read_text();parts=re.split(r'(?=^## [1-8]\. )',before,flags=re.M)
 add={4:'''Compact negative-volume diagnostics are now implemented and production-linked interface tests pass. For each native interior cell, retain the first and last below-threshold actual endpoints, minimum signed volume with its earliest time and step, negative-state step count, entry/recovery counts and initial-below flag. At every threshold transition, retain the actual before/after clocks and volumes, applied horizontal increment, rainfall and post-addition source increment, plus the four signed native-face exchanges and their geometric context. Keep individually rounded face sums, grouped-continuity differences and double-storage remainders separate. Missing faces and unavailable crossing times remain explicit. Initial negative storage does not create a fictitious triggering event. These are diagnostic fields, not new final prediction inputs.''',6:'''Water-group summaries use direct open prescribed-boundary connections with explicit multiple memberships and a separate unconnected class. Preserve distinct group codes even when water names coincide. Crossing-face exchange summaries count observed transitions and are not substitutes for full-event budgets. A recorded crossing time is an actual step-end observation; its continuous occurrence remains bracketed by adjacent endpoints, and negative-step counts do not establish exact continuous duration. The fixed whole-domain native geometry passes a production-linked metadata fixture, and prescribed-array tests preserve the original budget with diagnostics enabled or disabled. No new hydraulic response or physical mechanism verdict is generated by these interface checks.''',7:'''The compact crossing/minimum/face diagnostic interface and water-group aggregation are now implemented in a version-bound CPU image and checked with prescribed arrays, full native topology, serial/parallel comparison and existing rainfall/budget regressions. This step invokes no hydraulic solver initialization or update and does not replay the completed controls, train, release labels or execute prospective scenarios. The old controls retain unavailable local crossing histories. Any next finite control replay requires a separate authorization and must bind the qualified image, activation request, native metadata and original scientific curves. Actual boundary wetting-and-drying causation and reference admission remain pending that evidence.'''}
 for i,part in enumerate(parts):
  if not part.startswith('## '):continue
  n=int(re.match(r'## (\d)',part).group(1))
  if n in add and add[n]not in part:parts[i]=part.rstrip()+'\n\n'+add[n]+'\n\n'
 p.write_text(''.join(parts));old=re.split(r'(?=^## [1-8]\. )',backup.read_text(),flags=re.M)
 changed={int(re.match(r'## (\d)',a).group(1))for a,b in zip(old,parts)if a!=b};assert changed=={4,6,7}
 dump(report/'anasop-update.json',{'sections_changed':[4,6,7],'responsible_skills':['data-preprocessing','estimation-framework-planning'],'human_record':'MILI-D-20261015-011','prior_sha256':sha(backup),'current_sha256':sha(p),'new_final_variables':0,'new_formulas':0,'other_sections_unchanged':True})
 print(json.dumps({'checks':len(v['checks']),'report':str(report/'review.html'),'hydraulic_runs':0}))
if __name__=='__main__':main()
